package net.civeira.phylax.feature.oauth.client.application.usecase.registerclient;

import java.security.SecureRandom;
import java.util.HexFormat;
import java.util.Optional;
import java.util.Set;
import java.util.UUID;

import jakarta.enterprise.context.ApplicationScoped;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.feature.oauth.client.domain.ClientAuthMethod;
import net.civeira.phylax.feature.oauth.client.domain.DcrInitialAccessToken;
import net.civeira.phylax.feature.oauth.client.domain.DcrMetadataPolicy;
import net.civeira.phylax.feature.oauth.client.domain.DcrRegistrationRules;
import net.civeira.phylax.feature.oauth.client.domain.DynamicClientData;
import net.civeira.phylax.feature.oauth.client.domain.DynamicClientRequest;
import net.civeira.phylax.feature.oauth.client.domain.exception.DynamicClientException;
import net.civeira.phylax.feature.oauth.client.domain.gateway.DcrInitialAccessTokenGateway;
import net.civeira.phylax.feature.oauth.client.domain.gateway.DynamicClientGateway;

/**
 * Registers a new OAuth client via Dynamic Client Registration (RFC 7591, task 2.1).
 *
 * <p>
 * Order, so that a rejected request spends nothing:
 * <ol>
 * <li>the tenant must accept registrations ({@code access_denied});</li>
 * <li>a usable initial access token of the tenant is always required ({@code invalid_token});</li>
 * <li>the metadata is validated against the tenant rules, with the token grants prevailing
 * ({@code invalid_client_metadata}, {@code invalid_redirect_uri});</li>
 * <li>one use of the token is spent atomically, so an exhausted token never registers a
 * client;</li>
 * <li>the client is created in the tenant of the endpoint. A confidential client gets a secret; a
 * public one ({@code none}) or one that signs assertions ({@code private_key_jwt}) does not. Both
 * get a registration access token. The clear values are returned only now: only their digests are
 * stored.</li>
 * </ol>
 */
@ApplicationScoped
@RequiredArgsConstructor
public class RegisterClientUsecase {

  private static final SecureRandom RANDOM = new SecureRandom();

  private final DynamicClientGateway gateway;
  private final DcrInitialAccessTokenGateway initialAccessTokens;

  /**
   * Registers a new dynamic client.
   *
   * @param params registration parameters
   * @return registration result with credentials
   */
  public RegisterClientResult register(RegisterClientParams params) {
    DcrRegistrationRules rules = gateway.readRegistrationRules(params.getTenant());
    if (!rules.enabled()) {
      throw DynamicClientException.registrationNotAllowed();
    }
    String token = params.getInitialAccessToken();
    DcrInitialAccessToken initial = Optional.ofNullable(token).filter(t -> !t.isBlank())
        .flatMap(t -> initialAccessTokens.findUsable(params.getTenant(), t))
        .orElseThrow(DynamicClientException::tokenRequired);
    DcrRegistrationRules effective = initial.allowedGrantTypes()
        .map(grants -> rules.withGrantTypes(Set.copyOf(grants))).orElse(rules);
    DynamicClientRequest metadata = DcrMetadataPolicy.validate(params.getRequest(), effective);
    if (!initialAccessTokens.consume(initial.uid())) {
      throw DynamicClientException.tokenRequired();
    }

    String clientId = UUID.randomUUID().toString();
    Optional<String> clientSecret = ClientAuthMethod.from(metadata.getTokenEndpointAuthMethod())
        .filter(ClientAuthMethod::usesSecret).map(m -> randomToken());
    String registrationAccessToken = randomToken();

    DynamicClientData meta = gateway.create(params.getTenant(), clientId, clientSecret,
        registrationAccessToken, metadata);

    return RegisterClientResult.builder().clientId(meta.getClientId())
        .clientSecret(clientSecret.orElse(null)).clientIdIssuedAt(meta.getClientIdIssuedAt())
        .clientSecretExpiresAt(0).registrationAccessToken(registrationAccessToken)
        .registrationClientUri(registrationClientUri(params.getIssuer(), meta.getClientId()))
        .request(metadata).build();
  }

  /**
   * RFC 7592 management URL of a client.
   *
   * @param issuer issuer of the tenant
   * @param clientId client identifier
   * @return the client configuration endpoint
   */
  public static String registrationClientUri(String issuer, String clientId) {
    return issuer + "/connect/" + clientId;
  }

  private static String randomToken() {
    byte[] bytes = new byte[32];
    RANDOM.nextBytes(bytes);
    return HexFormat.of().formatHex(bytes);
  }
}
